// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, address u, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(u != address(0));
        uint256 amt = uint256(amount);
        vm.deal(actor, amt);

        vm.prank(actor);
        c.addToBalance{value: amt}();

        vm.prank(actor);
        uint256 reported = c.getBalance(u);

        vm.prank(u);
        uint256 actual = c.getBalance(u);

        assertTrue(reported == actual);
    }
}
